@dataclasses.dataclass
class RcState:
    """Complete command state of a control source, sent continuously (25-50 Hz). Carries the hard motor enable (safety.md section 3)."""
    PORT: ClassVar[Optional[int]] = 0x10
    IS_HEARTBEAT: ClassVar[bool] = False
    QOS: ClassVar[int] = 0  # control
    LATEST: ClassVar[bool] = True
    AIR_ELIGIBLE: ClassVar[bool] = True
    AIR_RATE_HZ: ClassVar[int] = 0
    USB_RATE_HZ: ClassVar[int] = 0
    MAX_SIZE: ClassVar[int] = 34
    MIN_SIZE: ClassVar[int] = 34
    CH_MIN: ClassVar[int] = -1000
    CH_MAX: ClassVar[int] = 1000
    CH_INVALID: ClassVar[int] = -32768
    FLAGS_SOURCE_OK: ClassVar[int] = 1
    flags: int = 0  # SOURCE_OK: the handset data is valid and fresh. Bits 1..7 are reserved (send 0, ignore on receive). RC_STATE is deliberately generic: only sticks, switches and source validity, no vehicle-specific meaning.
    reserved: int = 0
    ch: list[int] = dataclasses.field(default_factory=lambda: [0] * 16)  # -1000..1000, 0 = centre, CH_INVALID = channel not provided

    def encode(self) -> bytes:
        """Wire bytes. Raises ValueError on out-of-range integers or wrong array lengths."""
        b = bytearray(34)
        _rt.put(b, '<B', 0, self.flags)
        _rt.put(b, '<B', 1, self.reserved)
        if len(self.ch) != 16:
            raise ValueError('ch needs 16 elements')
        for i, v in enumerate(self.ch):
            _rt.put(b, '<h', 2 + i * 2, v)
        return bytes(b)

    @classmethod
    def decode(cls, data) -> "RcState":
        """Raises ValueError if shorter than MIN_SIZE. Longer input is accepted, extra bytes ignored."""
        data = bytes(data)
        if len(data) < cls.MIN_SIZE:
            raise ValueError('RC_STATE: payload too short (%d < 34)' % len(data))
        t = cls()
        t.flags = _rt.get(data, '<B', 0)
        t.reserved = _rt.get(data, '<B', 1)
        t.ch = [_rt.get(data, '<h', 2 + i * 2) for i in range(16)]
        return t


@dataclasses.dataclass
class Request:
    """One-shot non-safety action with an idempotent id. The action enum is in starship.toml (RequestAction). Exception: action LINK_UPLOAD_MODE (target = link module node id, 2 = TX, 3 = RX) makes that module stop the air link and enter its over-the-air firmware upload (WiFi) mode. It is always honoured with no safety condition (the module cannot know if the vehicle is flying), so senders must never send it unintentionally; arg_i and arg_f are 0, REQUEST_ACK detail is 0."""
    PORT: ClassVar[Optional[int]] = 0x11
    IS_HEARTBEAT: ClassVar[bool] = False
    QOS: ClassVar[int] = 2  # event
    LATEST: ClassVar[bool] = False
    AIR_ELIGIBLE: ClassVar[bool] = True
    AIR_RATE_HZ: ClassVar[int] = 0
    USB_RATE_HZ: ClassVar[int] = 0
    MAX_SIZE: ClassVar[int] = 12
    MIN_SIZE: ClassVar[int] = 12
    req_id: int = 0  # non-zero, new per action, reused on retry
    action: int = 0
    target: int = 0
    arg_i: int = 0
    arg_f: float = 0.0

    def encode(self) -> bytes:
        """Wire bytes. Raises ValueError on out-of-range integers or wrong array lengths."""
        b = bytearray(12)
        _rt.put(b, '<H', 0, self.req_id)
        _rt.put(b, '<B', 2, self.action)
        _rt.put(b, '<B', 3, self.target)
        _rt.put(b, '<i', 4, self.arg_i)
        _rt.put_f32(b, 8, self.arg_f)
        return bytes(b)

    @classmethod
    def decode(cls, data) -> "Request":
        """Raises ValueError if shorter than MIN_SIZE. Longer input is accepted, extra bytes ignored."""
        data = bytes(data)
        if len(data) < cls.MIN_SIZE:
            raise ValueError('REQUEST: payload too short (%d < 12)' % len(data))
        t = cls()
        t.req_id = _rt.get(data, '<H', 0)
        t.action = _rt.get(data, '<B', 2)
        t.target = _rt.get(data, '<B', 3)
        t.arg_i = _rt.get(data, '<i', 4)
        t.arg_f = _rt.get(data, '<f', 8)
        return t


